(()=>{"use strict";function t(){fetch("http://localhost:3002/api/reports?limit=5",{headers:{"Content-Type":"application/json"}}).then((t=>t.json())).then((t=>{const e=document.getElementById("report-list");e?0!==t.length?e.innerHTML=t.map((t=>{const e=new Date(t.updated_at).toLocaleString("en-US",{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"});return`\n          <li>\n            <div class="report-text">${t.element_text||"No text provided"}</div>\n            <div class="report-time">${e}</div>\n          </li>\n        `})).join(""):e.innerHTML='<div class="no-reports">No reports found</div>':console.error("Report list element not found")})).catch((t=>{const e=document.getElementById("report-list");e&&(e.innerHTML='<div class="no-reports">Failed to load reports</div>'),console.error("Error fetching reports:",t)}))}t(),setInterval(t,3e4)})();